<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);
$checks=[];
$read=static function(string $path) use($root): string { $file=$root.'/'.$path; if(!is_file($file)) throw new RuntimeException('Missing source: '.$path); return (string)file_get_contents($file); };
$assert=static function(string $name,bool $ok) use(&$checks): void { $checks[]=['name'=>$name,'ok'=>$ok]; if(!$ok) fwrite(STDERR,"FAIL: {$name}\n"); };
$aics=$read('aics/records.php');
$aicsTrash=$read('aics/trash.php');
$maifipDelete=$read('maifip/delete_record.php');
$maifipTrash=$read('maifip/trash.php');
$aicsTickets=$read('aics/tickets.php');
$maifipReview=$read('maifip/ticket_review.php');
$assert('AICS direct delete requires edit_records capability',str_contains($aics,"fams_current_type_allows('AICS','edit_records')"));
$assert('AICS direct delete rechecks office scope under row lock',str_contains($aics,'LIMIT 1 FOR UPDATE')&&str_contains($aics,'can_access_record_scope($row)'));
$assert('AICS direct delete archives full payload and deletes transactionally',str_contains($aics,'fams_archive_record_with_history')&&str_contains($aics,'fams_shared_transaction'));
$assert('AICS legacy records.php restore action is blocked',str_contains($aics,"action']??'')==='restore_record'")&&str_contains($aics,'http_response_code(405)'));
$assert('AICS restoration is administrator-only with capability and CSRF',str_contains($aicsTrash,"fams_current_type_allows('AICS','edit_records')")&&str_contains($aicsTrash,'!user_is_admin()')&&str_contains($aicsTrash,'verify_csrf()'));
$assert('AICS restoration locks archive and control sequence',str_contains($aicsTrash,'GET_LOCK')&&str_contains($aicsTrash,'restored_at IS NULL LIMIT 1 FOR UPDATE'));
$assert('AICS restore marks archive and audits in same transaction',str_contains($aicsTrash,'UPDATE fams_deleted_records SET restored_at=NOW()')&&str_contains($aicsTrash,'log_action($db'));
$assert('AICS restore rejects payload fields absent from destination schema',str_contains($aicsTrash,'INFORMATION_SCHEMA.COLUMNS')&&str_contains($aicsTrash,'unsupported field'));
$assert('MAIFIP direct delete is POST-only with CSRF and capability',str_contains($maifipDelete,"REQUEST_METHOD']!=='POST'")&&str_contains($maifipDelete,'verify_csrf()')&&str_contains($maifipDelete,"fams_current_type_allows('MAIFIP','edit_records')"));
$assert('MAIFIP direct delete locks facility-qualified record and checks editable state',str_contains($maifipDelete,'WHERE id=? AND facility=? LIMIT 1 FOR UPDATE')&&str_contains($maifipDelete,'can_edit_existing_record($record)'));
$assert('MAIFIP direct delete archives full payload and audits transactionally',str_contains($maifipDelete,'fams_archive_record_with_history')&&str_contains($maifipDelete,'fams_shared_transaction'));
$assert('MAIFIP restore is administrator-only with capability and CSRF',str_contains($maifipTrash,"fams_current_type_allows('MAIFIP','edit_records')")&&str_contains($maifipTrash,'!user_is_admin()')&&str_contains($maifipTrash,'verify_csrf()'));
$assert('MAIFIP restore locks facility archive and sequence',str_contains($maifipTrash,'GET_LOCK')&&str_contains($maifipTrash,'system_key=? AND facility=? AND restored_at IS NULL LIMIT 1 FOR UPDATE'));
$assert('MAIFIP restore marks archive and audits in same transaction',str_contains($maifipTrash,'UPDATE fams_deleted_records SET restored_at=NOW()')&&str_contains($maifipTrash,'log_action($db'));
$assert('MAIFIP restore rejects payload fields absent from destination schema',str_contains($maifipTrash,'INFORMATION_SCHEMA.COLUMNS')&&str_contains($maifipTrash,'unsupported field'));
$assert('AICS ticket-approved delete shares archive transaction',str_contains($aicsTickets,'_base_record_version')&&str_contains($aicsTickets,'fams_archive_record_with_history')&&str_contains($aicsTickets,'DELETE FROM aics_assistance_records'));
$assert('MAIFIP ticket-approved delete shares archive transaction',str_contains($maifipReview,'_base_record_version')&&str_contains($maifipReview,'fams_archive_record_with_history')&&str_contains($maifipReview,'DELETE FROM assistance_records'));
$archiveRuntime=$read('core/audit_runtime.php');
$assert('Shared archive helper snapshots record history and detaches ticket references',str_contains($archiveRuntime,'history_payload')&&str_contains($archiveRuntime,'record_control_number=COALESCE(record_control_number,?)'));
$registry=json_decode($read('maintenance/endpoint-registry.json'),true,512,JSON_THROW_ON_ERROR);
$paths=array_column($registry['routes'],'path');
$assert('Deletion/restoration routes are documented in endpoint registry',count(array_intersect(['aics/records.php','aics/trash.php','aics/tickets.php','maifip/delete_record.php','maifip/trash.php','maifip/ticket_review.php'],$paths))===6);
$failed=count(array_filter($checks,static fn($c)=>!$c['ok']));
printf("Deletion/restoration enforcement: %d/%d passed\n",count($checks)-$failed,count($checks));
exit($failed===0?0:1);
